from decimal import Decimal, ROUND_HALF_UP
from django.db import migrations, models

OLD = Decimal("0.0005")   # the old fallback (0.05%) used when no LoanConfig row existed
NEW = Decimal("0.005")    # the company rate: 0.5% per month


def fix_rates(apps, schema_editor):
    """Loans saved with the wrong 0.05% fallback get 0.5% and their monthly repayment recomputed
    (total = amount + amount x rate x months, spread over the months). Only that exact wrong value
    is touched; anything staff set on purpose stays as it is."""
    LoanConfig = apps.get_model("accounts", "LoanConfig")
    LoanApplication = apps.get_model("accounts", "LoanApplication")
    LoanConfig.objects.filter(interest_rate_monthly=OLD).update(interest_rate_monthly=NEW)
    for loan in LoanApplication.objects.filter(interest_rate_monthly=OLD).only("id", "amount", "term_months"):
        monthly = None
        if loan.amount and loan.term_months:
            total = loan.amount + loan.amount * NEW * loan.term_months
            monthly = (total / loan.term_months).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        LoanApplication.objects.filter(id=loan.id).update(interest_rate_monthly=NEW, monthly_repayment=monthly)


